def _depth_to_rgb(unit: np.ndarray, colour: bool) -> np.ndarray:
    g = (np.clip(unit, 0.0, 1.0) * 255.0 + 0.5).astype(np.uint8)
    if colour:
        return cv2.cvtColor(cv2.applyColorMap(g, cv2.COLORMAP_TURBO), cv2.COLOR_BGR2RGB)
    return np.repeat(g[:, :, None], 3, axis=2)


def _hex_rgb(colour: str) -> Tuple[int, int, int]:
    c = colour.lstrip("#")
    return int(c[0:2], 16), int(c[2:4], 16), int(c[4:6], 16)


def _readable_on(colour: str) -> str:
    try:
        r, g, b = _hex_rgb(colour)
    except (ValueError, IndexError):
        return "#ffffff"
    return "#000000" if (0.299 * r + 0.587 * g + 0.114 * b) > 150 else "#ffffff"


def _get_path(obj: Any, path: Tuple[str, ...]) -> Any:
    for name in path:
        obj = getattr(obj, name)
    return obj


def _set_path(obj: Any, path: Tuple[str, ...], value: Any) -> None:
    for name in path[:-1]:
        obj = getattr(obj, name)
    current = getattr(obj, path[-1])
    if isinstance(current, bool):
        value = bool(value)
    elif isinstance(current, int):
        value = int(round(float(value)))
    elif isinstance(current, float):
        value = float(value)
    setattr(obj, path[-1], value)


def _default_for(path: Tuple[str, ...], target: str) -> Any:
    base = edit_ops.LayerSettings() if target == "layer" else edit_ops.GlobalSettings()
    return _get_path(base, path)


def _remove_quietly(path: str) -> None:
    try:
        os.remove(path)
    except OSError:
        pass


def _pct(v: float) -> str:
    return f"{float(v) * 100:+.0f}%"


def _pct0(v: float) -> str:
    return f"{float(v) * 100:.0f}%"


def _times(v: float) -> str:
    return f"{float(v):.2f}x"


def _px(v: float) -> str:
    return f"{int(round(float(v)))} px"


def _px_signed(v: float) -> str:
    return f"{int(round(float(v))):+d} px"


def _frames(v: float) -> str:
    n = int(round(float(v)))
    return "off" if n <= 0 else f"\u00b1{n} fr"


