class _TkVar:
    """A tk variable: a value, and write traces that fire as Tk's do."""

    def __init__(self, master=None, value=None):
        self._value = value
        self._traces = []

    def get(self):
        return self._value

    def set(self, value):
        self._value = value
        for cb in list(self._traces):
            cb("", "", "write")

    def trace_add(self, _mode, callback):
        self._traces.append(callback)
        return str(id(callback))

    def trace_remove(self, *_a):
        pass


class _BoolVar(_TkVar):
    def __init__(self, master=None, value=False):
        super().__init__(master, bool(value))


class _IntVar(_TkVar):
    def __init__(self, master=None, value=0):
        super().__init__(master, int(value))


class _DoubleVar(_TkVar):
    def __init__(self, master=None, value=0.0):
        super().__init__(master, float(value))


class _StrVar(_TkVar):
    def __init__(self, master=None, value=""):
        super().__init__(master, str(value))


class _Tk:
    StringVar, BooleanVar, IntVar, DoubleVar, Variable = _StrVar, _BoolVar, _IntVar, _DoubleVar, _TkVar
