class _Widget:
    """A widget v1's logic configures: what it is told goes to the hooks."""

    def __init__(self, hooks, name):
        self._hooks = hooks
        self._name = name
        self._opts = {}

    def configure(self, **kw):
        self._opts.update(kw)
        self._hooks.widget(self._name, dict(kw))

    config = configure

    def cget(self, key):
        return self._opts.get(key)

    def __setitem__(self, key, value):
        self._opts[key] = value
        self._hooks.widget(self._name, {key: value})

    def __getitem__(self, key):
        return self._opts.get(key)

    def focus_set(self):
        pass


class _Listbox(_Widget):
    """v1's layer list (a tk.Listbox): its rows, colours and selection."""

    def __init__(self, hooks, name):
        super().__init__(hooks, name)
        self.items = []
        self.colours = []
        self.selected = ()

    def _changed(self):
        self._hooks.widget(self._name, {"items": list(self.items), "colours": list(self.colours),
                                          "selected": list(self.selected)})

    def delete(self, first, last=None):
        if last == "end":
            self.items, self.colours = self.items[:int(first)], self.colours[:int(first)]
        else:
            i = int(first)
            if 0 <= i < len(self.items):
                del self.items[i]
                del self.colours[i]
        self._changed()

    def insert(self, index, text):
        i = len(self.items) if index == "end" else int(index)
        self.items.insert(i, str(text))
        self.colours.insert(i, "")
        self._changed()

    def itemconfigure(self, index, **kw):
        if "foreground" in kw and 0 <= int(index) < len(self.colours):
            self.colours[int(index)] = kw["foreground"]
            self._changed()

    def selection_clear(self, *_a):
        self.selected = ()
        self._changed()

    def selection_set(self, index):
        self.selected = (int(index),)
        self._changed()

    def curselection(self):
        return self.selected


class _MessageBoxShim:
    """v1's messagebox. Errors and notes go to the hooks. A yes/no question
    is answered from ``answers`` (by its text) when QML has already asked it;
    otherwise it is recorded in ``asked`` and answered No, so the action
    stops where v1 would have waited -- the controller asks, then runs the
    action again with the answer in place."""

    def __init__(self):
        self.hooks = None
        self.answers = {}
        self.asked = []

    def _send(self, kind, title, message):
        if self.hooks is not None:
            self.hooks.message(kind, str(title), str(message))

    def showerror(self, title="", message="", **_kw):
        self._send("error", title, message)

    def showwarning(self, title="", message="", **_kw):
        self._send("warning", title, message)

    def showinfo(self, title="", message="", **_kw):
        self._send("info", title, message)

    def askyesno(self, title="", message="", **_kw):
        if message in self.answers:
            return bool(self.answers[message])
        self.asked.append((str(title), str(message)))
        return False


messagebox = _MessageBoxShim()


class _FileDialogShim:
    """v1's file pickers inside its logic (Pick From Last DepthCrafter Job):
    ``answer`` is QML's choice; with none, the request is recorded in
    ``asked`` for QML to open its own dialog."""

    answer = ""
    asked = None

    def askopenfilename(self, **kw):
        if self.answer:
            return self.answer
        self.asked = dict(kw)
        return ""


filedialog = _FileDialogShim()


