class DepthEditEngine:
    """v1 DepthEditorGUI without its window.

    hooks -- message(kind, title, text), widget(name, options), after(ms, fn)
             -> id, after_cancel(id), preview(), page(name), settings_save(data)
             ... see stages/depthedit/controller.py
    """

    # ---- the Tk surface ------------------------------------------------------------

    def after(self, delay_ms, fn=None, *args):
        if fn is None:
            return None
        return self.hooks.after(int(delay_ms or 0), (lambda: fn(*args)) if args else fn)

    def after_cancel(self, job):
        self.hooks.after_cancel(job)

    def winfo_toplevel(self):
        return self

    def title(self, *_a):
        pass

    def _only_saving(self):
        """Nothing pending but the open project's save (bug sweep A9: Load
        Clip queues it on the worker, before the load)."""
        if self._busy_job not in (None, "Saving project"):
            return False
        return all(j is not None and j[0] == "Saving project" for j in list(self._jobs.queue))

    # ---- the widget-only methods (STUBS) ---------------------------------------------

    def _create_widgets(self):
        """v1 builds the window; here: the widgets its logic reads, and the
        edit controls (v1 _slider_row / the builders register them), as vars."""
        self.layer_list = _Listbox(self.hooks, "layer_list")
        self.frame_slider = _Widget(self.hooks, "frame_slider")
        self.frame_label = _Widget(self.hooks, "frame_label")
        self.canvas = _Widget(self.hooks, "canvas")
        self.track_progress = _Widget(self.hooks, "track_progress")
        self.render_progress = _Widget(self.hooks, "render_progress")
        for name in ("track_btn", "stop_btn", "render_btn", "render_stop_btn", "install_btn", "weights_btn",
                     "model_btn", "import_btn", "sam_status"):
            setattr(self, name, _Widget(self.hooks, name))
        #: path -> (var, spec): every edit control, as v1 registers them.
        self.control_specs = {}
        for table in (LAYER_SLIDERS, EDGE_SLIDERS, GRADIENT_SLIDERS):
            for spec in table:
                path, lo, hi = spec[0], spec[2], spec[3]
                var = tk.IntVar(value=0) if isinstance(lo, int) and isinstance(hi, int) else tk.DoubleVar(value=0.0)
                self._layer_controls.append((path, var))
                self.control_specs[path] = spec
        for path in (("fill_holes",), ("gradient", "enabled"), ("gradient", "follow_object")):
            self._layer_controls.append((path, tk.BooleanVar(value=False)))
        self._layer_controls.append((("gradient", "shape"), tk.StringVar(value="Linear")))
        self._layer_controls.append((("gradient", "blend"), tk.StringVar(value="Replace")))
