    # ---- v1 DepthEditorGUI methods, verbatim below ----------------------------------

    # -- v1 DepthEditorGUI.__init__ (depth_editor_gui.py:98)
    def __init__(self, master=None, shell=None, hooks=None) -> None:
        self.hooks = hooks
        messagebox.hooks = hooks
        self.shell = shell
        if self.shell is None:
            self.winfo_toplevel().title("StereoCrafter Depth Map Editor")

        self.help_data = self._load_help_texts()

        # -- clip and project --------------------------------------------
        self.info: Optional[depth_io.ClipInfo] = None
        self.codes: Optional[np.ndarray] = None  # (N, H, W) uint16
        self.rgb: Optional[np.ndarray] = None  # (N, H, W, 3) uint8 at hires.view_size (v2)
        self.rgb_aspect: float = 16 / 9
