    # -- v1 DepthEditorGUI._submit (depth_editor_gui.py:694)
    def _submit(self, name: str, fn: Callable[[], None]) -> None:
        self._submitted = getattr(self, "_submitted", 0) + 1  # v2: see the controller's _edit
        self._jobs.put((name, fn))
        self._set_busy_ui()

    # -- v1 DepthEditorGUI._worker_loop (depth_editor_gui.py:698)
    def _worker_loop(self) -> None:
        while True:
            item = self._jobs.get()
            if item is None:
                return
            name, fn = item
            self._busy_job = name
            self._ui(self._set_busy_ui)  # v2: the buttons as the running job has them
            try:
                fn()
            except Exception as e:  # a job's failure must not kill the worker
                logger.exception("Depth Map Editor job %r failed", name)
                self._ui(self._show_error, f"{name} failed", f"{type(e).__name__}: {e}")
            finally:
                self._busy_job = None
                self._stop.clear()
                self._ui(self._set_busy_ui)

    # -- v1 DepthEditorGUI._ui (depth_editor_gui.py:715)
    def _ui(self, fn: Callable, *args) -> None:
        """Run `fn(*args)` on the main thread at the next poll."""
        self._ui_queue.put((fn, args))

