    def holds_gpu(self) -> bool:
        return self.engine.loaded

    # -- v1 DepthEditorGUI.release_gpu (depth_editor_gui.py:769)
    def release_gpu(self) -> None:
        """Unload SAM on the worker thread -- the thread that loaded it.

        SAM 3.1 turns bf16 autocast on in the thread that builds it, and
        autocast is per-thread, so unloading from here would leave it on in
        the worker. The unload is queued behind any job running; the Event it
        sets is returned, and the claiming stage waits on it off the UI thread
        (gpu_jobs.wait_for_releases).
        """
        if not self.engine.loaded:
            return None
        done = threading.Event()

        def job() -> None:
            try:
                self.engine.unload()
            finally:
                done.set()

        self._submit("Unloading SAM 3", job)
        self._refresh_sam_status()
        return done  # v2: waited for off the UI thread (#14)

    # -- v1 DepthEditorGUI.stop_processing (depth_editor_gui.py:794)
    def stop_processing(self) -> None:
        self._request_stop()

    # -- v1 DepthEditorGUI.shutdown (depth_editor_gui.py:797)
    def shutdown(self) -> None:
        self._closing = True
        self._request_stop()
        self._save_settings()
        if self._poll_id is not None:
            try:
                self.after_cancel(self._poll_id)
            except Exception:
                pass
        # Unloaded as the worker's last job, on the thread that loaded it.
        self._jobs.put(("Unloading SAM 3", self.engine.unload))
        self._jobs.put(None)
        self._worker.join(timeout=10)
        if self.engine.loaded:  # the worker was stuck in a long job
            try:
                self.engine.unload()
            except Exception:
                logger.debug("SAM 3 unload at shutdown raised", exc_info=True)

    # -- v1 DepthEditorGUI._depthcrafter_record (depth_editor_gui.py:847)
    def _depthcrafter_record(self) -> Dict[str, Any]:
        try:
            from core.ui.job_handoff import get_record

            return get_record("depthcrafter") or {}
        except Exception:
            return {}

    # -- v1 DepthEditorGUI._pick_from_depthcrafter (depth_editor_gui.py:855)
    def _pick_from_depthcrafter(self) -> None:
        record = self._depthcrafter_record()
        if not record.get("source"):
            messagebox.showinfo("Depth Map Editor", "No finished DepthCrafter job is recorded yet.",
                                parent=self.winfo_toplevel())
            return
        from core.ui.job_handoff import resolve_subfolder

        # DepthCrafter moves each clip into <source>/finished as it completes.
        start = resolve_subfolder(record["source"], "finished")
        if os.path.isfile(start):
            self.rgb_path_var.set(start)
            return
        path = filedialog.askopenfilename(parent=self.winfo_toplevel(), title="Pick a clip DepthCrafter processed",
                                          initialdir=start,
                                          filetypes=[("Video", " ".join(f"*{e}" for e in VIDEO_EXTENSIONS))])
        if path:
            self.rgb_path_var.set(path)

    # -- v1 DepthEditorGUI._auto_pair_depth (depth_editor_gui.py:874)
    def _auto_pair_depth(self) -> None:
        """Fill the depth box from the source clip's name, if the map can be found."""
        rgb = self.rgb_path_var.get().strip()
        if not rgb or not os.path.isfile(rgb):
            return
        stem = os.path.splitext(os.path.basename(rgb))[0]
        folders = [os.path.dirname(self.depth_path_var.get()), self._depthcrafter_record().get("depth", ""),
                   os.path.dirname(rgb)]
        for folder in folders:
            if not folder:
                continue
            for candidate in (os.path.join(folder, f"{stem}_depth.mp4"),
                              os.path.join(folder, "finished", f"{stem}_depth.mp4")):
                if os.path.isfile(candidate):
                    self.depth_path_var.set(candidate.replace("\\", "/"))
                    return

    # -- v1 DepthEditorGUI._load_clip (depth_editor_gui.py:891)
    def _load_clip(self) -> None:
        rgb = self.rgb_path_var.get().strip()
        depth = self.depth_path_var.get().strip()
        if not os.path.isfile(depth):
            messagebox.showerror("Depth Map Editor", "Choose a depth map first.", parent=self.winfo_toplevel())
            return
        if rgb and not os.path.isfile(rgb):
            messagebox.showerror("Depth Map Editor", f"Source video not found:\n{rgb}", parent=self.winfo_toplevel())
            return
        if self._job_pending() and not self._only_saving():  # v2: bug sweep A9
            messagebox.showinfo("Depth Map Editor", "Wait for the current job to finish.", parent=self.winfo_toplevel())
            return
        # The default output is an "edited" folder beside the depth maps. A
        # folder the user chose is kept; a DEFAULT left over from a clip in
        # another folder is moved, or one chapter's edits would land in the
        # previous chapter's folder.
        out_dir = self.output_dir_var.get().strip()
        depth_dir = os.path.normcase(os.path.abspath(os.path.dirname(depth)))
        stale_default = (os.path.basename(out_dir.rstrip("/\\")) == "edited"
                         and os.path.normcase(os.path.abspath(os.path.dirname(out_dir.rstrip("/\\")))) != depth_dir)
        if os.path.basename(out_dir.rstrip("/\\")).lower() == "edit_history":  # v2
            stale_default = True
        if not out_dir or stale_default:
            out_dir = os.path.join(os.path.dirname(depth), "edited").replace("\\", "/")
            self.output_dir_var.set(out_dir)
        self._save_settings()
        self._submit("Loading clip", lambda: self._load_job(rgb, depth, out_dir))

    # -- v1 DepthEditorGUI._load_job (depth_editor_gui.py:917)
    def _load_job(self, rgb: str, depth: str, out_dir: str) -> None:
        self._ui(self._status, "Reading depth map...")
        info = depth_io.probe(depth)
        codes = depth_io.load_codes(
            info, progress=lambda n, t: self._ui(self._status, f"Reading depth map... {n}/{t}"), stop=self._stop)
        if self._stop.is_set():
            return
        rgb_frames = None
        aspect = info.width / max(info.height, 1)
        warning = ""
        if rgb:
            rgb_info = depth_io.probe(rgb, count=False)  # v2: counted below, without a decode
            rgb_info.num_frames = depth_io.count_frames(rgb, info.num_frames)
            aspect = rgb_info.width / max(rgb_info.height, 1)
            if rgb_info.num_frames != info.num_frames:
                warning = (f"Frame counts differ: source {rgb_info.num_frames}, depth {info.num_frames}. "
                           "Masks from the RGB are matched frame by frame from the start.")
            vw, vh = hires.view_size((rgb_info.width, rgb_info.height), (info.width, info.height),
                                     info.num_frames, RGB_CACHE_BUDGET)  # v2: the RGB view at up to 720p
            need = info.num_frames * vw * vh * 3
            if need <= RGB_CACHE_BUDGET:
                buf = np.empty((len(codes), vh, vw, 3), np.uint8)  # v2: no list + stack
                got = 0
                for i, f in enumerate(depth_io.iter_rgb(rgb, vw, vh, self._stop)):
                    buf[got] = f
                    got += 1
                    if i % 8 == 0:
                        self._ui(self._status, f"Reading source video... {i + 1}/{rgb_info.num_frames}")
                    if got >= len(codes):
                        break
                if got:
                    rgb_frames = buf[:got]   # a view: no second copy
                del buf
            else:
                warning = "Source is too long to hold for the RGB view; SAM 3 can still segment it."
        # The project that was saved beside an earlier render of this clip, if any.
        proj_path = project_path_for(out_dir, depth)
        project = None
        if os.path.isfile(proj_path):
            try:
                project = Project.load(proj_path, info.height, info.width)
            except Exception:
                logger.exception("Could not read %s; starting a new edit", proj_path)
        if project is None:
            project = Project()
        project.rgb_path, project.depth_path = rgb, depth
        # A new clip means new frames; the old session is for the old clip.
        self.engine.close_session()
        self._ui(self._clip_loaded, info, codes, rgb_frames, aspect, project, warning, os.path.isfile(proj_path))

    # -- v1 DepthEditorGUI._clip_loaded (depth_editor_gui.py:961)
    def _clip_loaded(self, info, codes, rgb_frames, aspect, project, warning, resumed) -> None:
        self.info, self.codes, self.rgb, self.rgb_aspect = info, codes, rgb_frames, aspect
        self.project = project
        self._results.clear()
        self.selected = 0 if project.layers else None
        n = len(codes)
        self.frame_slider.configure(from_=0, to=max(n - 1, 0), number_of_steps=max(n - 1, 1))
        self.frame_idx = 0
        self.frame_var.set(0)
        if not self.rgb_path_var.get().strip() and self.view_var.get() == "RGB":
            self.view_var.set("Depth")
        self._load_global_controls()
        self._refresh_layer_panel()
        msg = f"Loaded {n} frames at {info.width}x{info.height}."
        if resumed:
            msg += f" Reopened the saved edit ({len(project.layers)} layers)."
        if warning:
            msg += " " + warning
        self._status(msg)
        self._schedule_preview()

