    # -- v1 DepthEditorGUI._refresh_sam_status (depth_editor_gui.py:1183)
    def _refresh_sam_status(self) -> None:
        missing = sam.missing_packages()
        lines = []
        ready = True
        if missing:
            lines.append("Needs packages: " + ", ".join(missing) + ".")
            ready = False
        default_ckpt = sam.checkpoint_path(sam.DEFAULT_VERSION)
        try:  # v2: the models folder may be elsewhere (Settings > Studio > Models)
            default_ckpt = default_ckpt.relative_to(_REPO_ROOT)
        except ValueError:
            pass
        if not sam.weights_present():
            lines.append(f"Needs weights: {default_ckpt} (gated on Hugging Face).")
            ready = False
        elif not sam.default_present():
            lines.append(f"Using {sam.model_label()}. Download Weights to upgrade to "
                         f"{sam.model_label(sam.DEFAULT_VERSION)}.")
        if not sam.cuda_available():
            lines.append("No CUDA GPU is available to PyTorch.")
            ready = False
        if ready:
            label = sam.model_label(self.engine.version)
            lines.append(f"{label} loaded." if self.engine.loaded
                         else f"{label} ready -- loads on first use (about 4 GB of VRAM).")
        if self._busy_job:
            lines.append(f"Working: {self._busy_job}...")
        self.sam_status_var.set("\n".join(lines))
        try:
            self.install_btn.configure(state=tk.NORMAL if missing else tk.DISABLED)
            # Stays available until the DEFAULT model is here, so an install
            # that only has the older checkpoint can upgrade from the GUI.
            self.weights_btn.configure(state=tk.DISABLED if sam.default_present() else tk.NORMAL)
            self.model_btn.configure(state=tk.NORMAL if self.engine.loaded else tk.DISABLED)
        except AttributeError:
            pass  # called before the buttons exist

    # -- v1 DepthEditorGUI._sam_ready (depth_editor_gui.py:1216)
    def _sam_ready(self) -> bool:
        if sam.missing_packages() or not sam.weights_present() or not sam.cuda_available():
            self.page_var.set("Segment")
            self._show_page()
            self._refresh_sam_status()
            self._status("SAM 3 is not set up yet -- see the Segment page.")
            return False
        return True

    # -- v1 DepthEditorGUI._resource_for (depth_editor_gui.py:1225)
    def _resource_for(self, layer: Layer) -> str:
        if layer.source == "Depth" or not self.project.rgb_path:
            return self.project.depth_path
        return self.project.rgb_path

    # -- v1 DepthEditorGUI._ensure_layer (depth_editor_gui.py:1230)
    def _ensure_layer(self) -> Layer:
        layer = self._layer()
        if layer is None:
            layer = self._new_layer()
        return layer

    # -- v1 DepthEditorGUI._session_for (depth_editor_gui.py:1236)
    def _session_for(self, layer: Layer, offload: bool) -> bool:
        """Open the right video and make `layer` the session's owner. Worker thread.

        Returns True if the layer's prompts were replayed, in which case the
        prompt that triggered this is already in and must not be sent again.
        """
        if not self.engine.loaded:
            _wait = getattr(self, "wait_gpu", None)  # v2: gpu_jobs.wait_for_releases (#14)
            if _wait is not None:
                _wait()
            self._ui(self._status, f"Loading {sam.model_label()} (first use takes a moment)...")
            prev, self._busy_job = self._busy_job, "Loading SAM 3"
            self._ui(self._refresh_sam_status)
            try:
                self.engine.load()
            finally:
                self._busy_job = prev
                self._ui(self._set_busy_ui)  # v2: back to the job's own buttons
        n = self.engine.open(self._resource_for(layer), offload)
        if n != self._num_frames():
            logger.warning("SAM 3 sees %d frames, the depth map has %d", n, self._num_frames())
        if self.engine.owner != layer.uid:
            results = self.engine.replay(layer.text, layer.text_frame, layer.clicks)
            self.engine.owner = layer.uid
            for frame, result in results.items():
                self._accept_result(layer, frame, result)
            return True
        return False

    # -- v1 DepthEditorGUI._accept_result (depth_editor_gui.py:1261)
    def _accept_result(self, layer: Layer, frame: int, result) -> None:
        """Store a prompt's mask for its frame. Worker thread; posts the redraw."""
        self._results[(layer.uid, frame)] = sam.pack_result(result)
        mask = sam.union_mask(result, self.info.height, self.info.width)
        layer.masks.set(frame, mask)
        hires.store_result(layer, frame, result, hires.source_size(self.project.rgb_path))  # v2
        self._ui(self._after_prompt, layer.uid)

    # -- v1 DepthEditorGUI._after_prompt (depth_editor_gui.py:1268)
    def _after_prompt(self, uid: str) -> None:
        self._refresh_layer_panel()
        self._schedule_preview()

    # -- v1 DepthEditorGUI._prompt_click (depth_editor_gui.py:1272)
    def _prompt_click(self, rel: Tuple[float, float], label: int, new_object: bool) -> None:
        if not self._sam_ready():
            return
        layer = self._ensure_layer()
        frame = self.frame_idx
        result = self._results.get((layer.uid, frame))
        hit = sam.object_at(result, *rel) if result else None
        if patches.wants_click(self, layer, frame, rel, label, hit):  # v2: a patch on a tracked layer
            patches.click(self, layer, frame, rel, label)
            return
        # Which object a click belongs to. Inside an object's mask: that one.
        # Outside every mask: the object clicked most recently, on ANY frame --
        # so a click on the part a tracked mask missed, on the frame where it
        # drifted, corrects that object rather than starting a new one. Only
        # Ctrl+click (or a layer with nothing clicked yet) starts a new object.
        current = layer.clicks[-1].obj_id if layer.clicks else None
        if new_object and label == 1:
            obj_id = max(CLICK_OBJ_BASE, layer.next_obj_id(result[0] if result else []))
        elif hit is not None:
            obj_id = hit
        elif current is not None:
            obj_id = current
        elif label == 0:
            self._status("Nothing to remove there -- click inside the object's mask.")
            return
        else:
            obj_id = max(CLICK_OBJ_BASE, layer.next_obj_id(result[0] if result else []))
        layer.clicks.append(Click(frame=frame, obj_id=obj_id, x=rel[0], y=rel[1], label=label))
        layer.tracked = False
        self._send_prompt(layer, frame, obj_id)

    # -- v1 DepthEditorGUI._prompt_box (depth_editor_gui.py:1300)
    def _prompt_box(self, a: Tuple[float, float], b: Tuple[float, float]) -> None:
        if not self._sam_ready():
            return
        layer = self._ensure_layer()
        frame = self.frame_idx
        result = self._results.get((layer.uid, frame))
        if patches.wants_box(layer):  # v2: a box on a tracked layer is a patch
            patches.box(self, layer, a, b)
            return
        obj_id = max(CLICK_OBJ_BASE, layer.next_obj_id(result[0] if result else []))
        x0, x1 = sorted((a[0], b[0]))
        y0, y1 = sorted((a[1], b[1]))
        # SAM 2's convention, which SAM 3's tracker keeps: a box is its two
        # corners as the object's FIRST two points, labelled 2 and 3.
        layer.clicks.append(Click(frame, obj_id, x0, y0, 2))
        layer.clicks.append(Click(frame, obj_id, x1, y1, 3))
        layer.tracked = False
        self._send_prompt(layer, frame, obj_id)

    # -- v1 DepthEditorGUI._send_prompt (depth_editor_gui.py:1316)
    def _send_prompt(self, layer: Layer, frame: int, obj_id: int) -> None:
        offload = self.offload_var.get()
        group = [c for c in layer.clicks if c.frame == frame and c.obj_id == obj_id]
        # Box corners first, whatever order they were added in.
        group.sort(key=lambda c: 0 if c.label in (2, 3) else 1)

        def job() -> None:
            if layer.text:
                # Always rebuilt from scratch: a click on a text-prompted
                # layer must turn its found objects into mask-seeded ones
                # (see Sam3Engine.replay), and a click sent straight into the
                # text session would break tracking for the whole layer.
                self.engine.owner = None
            replayed = self._session_for(layer, offload)
            if not replayed:
                result = self.engine.add_points(frame, obj_id, [(c.x, c.y) for c in group], [c.label for c in group])
                self._accept_result(layer, frame, result)
            self._ui(self._status, f"{layer.name}: object {obj_id} updated on frame {frame + 1}. "
                                   "Start Tracking when it looks right.")

        self._submit("Segmenting", job)
        self._refresh_layer_panel()
        self._schedule_preview()

    # -- v1 DepthEditorGUI._find_text (depth_editor_gui.py:1340)
    def _find_text(self) -> None:
        text = self.text_var.get().strip()
        if not text or self.codes is None or not self._sam_ready():
            return
        layer = self._ensure_layer()
        layer.text, layer.text_frame = text, self.frame_idx
        layer.tracked = False
        if not layer.name or layer.name.startswith("Layer "):
            layer.name = text
        offload = self.offload_var.get()

        def job() -> None:
            self.engine.owner = None  # force the replay, which starts from the text
            self._session_for(layer, offload)
            found = self._results.get((layer.uid, layer.text_frame))
            count = len(found[0]) if found else 0
            self._ui(self._status, f'"{text}": {count} found on frame {layer.text_frame + 1}.'
                     + ("" if count else " Try other words, another frame, or click the object."))

        self._submit("Segmenting", job)
        self._refresh_layer_panel()

    # -- v1 DepthEditorGUI._clear_prompts (depth_editor_gui.py:1362)
    def _clear_prompts(self) -> None:
        layer = self._layer()
        if layer is None:
            return
        layer.text, layer.clicks, layer.tracked = "", [], False
        layer.masks.clear()
        layer.masks_hi = None  # v2
        patches.clear(self, layer)  # v2
        for key in [k for k in self._results if k[0] == layer.uid]:
            del self._results[key]
        if self.engine.owner == layer.uid:
            self.engine.owner = None
        self._refresh_layer_panel()
        self._schedule_preview()

    # -- v1 DepthEditorGUI._track (depth_editor_gui.py:1375)
    def _track(self, direction: str = "both", start: Optional[int] = None) -> None:
        # v2 (user, 2026-10-05): direction "forward" = Track From Here, "backward" =
        # Track Backwards, both from `start` (the frame showing); the frames
        # outside the run keep the masks they had
        layer = self._layer()
        if layer is None or not layer.has_prompts():
            self._status("Select objects first: click one, drag a box, or Find by name.")
            return
        if not self._sam_ready():
            return
        offload = self.offload_var.get()
        n = self._num_frames()
        h, w = self.info.height, self.info.width
        partial = direction in ("forward", "backward")  # v2
        if partial:
            start = self.frame_idx if start is None else max(0, min(int(start), n - 1))
        # the SAM 3 backward pass starts the frame before (the frame itself belongs to
        # the forward pass): back = the previous frames only
        total = (n - start if direction == "forward" else start) if partial else n

        if patches.pending(layer):  # v2: a patch pending: tracked alone, added to the masks
            patches.track(self, layer, offload, direction, start if partial else None, total)
            return

        def job() -> None:
            self._session_for(layer, offload)
            fresh = MaskStore(h, w)
            fresh_hi = hires.new_store(hires.source_size(self.project.rgb_path), (w, h)) if layer.source == "RGB" else None  # v2
            if partial and layer.masks is not None and (layer.masks.height, layer.masks.width) == (h, w):
                fresh = layer.masks.snapshot()      # v2: frames outside the run keep their masks
                hi = layer.masks_hi
                if fresh_hi is not None and hi is not None and (hi.width, hi.height) == (fresh_hi.width, fresh_hi.height):
                    fresh_hi = hi.snapshot()
            done = 0
            for frame, result in self.engine.propagate(direction=direction, start_frame=start if partial else None):  # v2
                if self._stop.is_set():
                    break
                if frame < n:
                    fresh.set(frame, sam.union_mask(result, h, w))
                    hires.put(fresh_hi, frame, result)  # v2
                    self._results[(layer.uid, frame)] = sam.pack_result(result)
                done += 1
                if done % 4 == 0:
                    self._ui(self._track_progress, done, total, frame)
            if self._stop.is_set():
                self._ui(self._status, "Tracking stopped; the layer keeps its previous masks.")
                return
            if layer.patch_clicks:  # v2: the layer's patches, tracked again and added in
                patches.propagate_into(self, layer, offload, fresh, fresh_hi, direction, start if partial else None)
                if self._stop.is_set():
                    self._ui(self._status, "Tracking stopped; the layer keeps its previous masks.")
                    return
            layer.patch_base = None  # v2
            layer.masks, layer.tracked = fresh, True
            layer.masks_hi = fresh_hi  # v2
            self._ui(self._track_progress, total, total, None)
            if partial:  # v2
                way = "forward from" if direction == "forward" else "back from"
                self._ui(self._status, f"{layer.name}: tracked {way} frame {start + 1} ({done} frames); "
                                       "the other frames keep their masks.")
            else:
                self._ui(self._status, f"{layer.name}: tracked through {n} frames ({len(fresh)} with the object).")
            self._ui(self._after_prompt, layer.uid)

        self._submit("Tracking", job)

    # -- v1 DepthEditorGUI._track_progress (depth_editor_gui.py:1409)
    def _track_progress(self, done: int, total: int, frame: Optional[int]) -> None:
        # Both directions are tracked, so the count can pass the frame total.
        self.track_progress["value"] = min(100.0, 100.0 * done / max(total, 1))
        if frame is not None:
            self._status(f"Tracking... frame {frame + 1}")

