    # -- v1 DepthEditorGUI._install_packages (depth_editor_gui.py:1425)
    def _install_packages(self) -> None:
        if self._job_pending():
            return
        self._status("Working out what would be installed...")

        def plan_job() -> None:
            code, out = installer.plan()
            self._ui(self._confirm_install, code, out)

        self._submit("Planning install", plan_job)

    # -- v1 DepthEditorGUI._confirm_install (depth_editor_gui.py:1436)
    def _confirm_install(self, code: int, plan_text: str) -> None:
        if code != 0:
            self._show_error("Install plan failed", plan_text[-1500:])
            return
        changes = [ln for ln in plan_text.splitlines() if ln.lstrip().startswith(("+", "-", "~"))]
        summary = "\n".join(changes) if changes else "(no package changes)"
        if not messagebox.askyesno(
                "Install SAM 3 packages",
                "uv will make these changes to this StereoCrafter environment "
                "(nothing is removed):\n\n" + summary + "\n\nGo ahead?",
                parent=self.winfo_toplevel()):
            self._status("Install cancelled.")
            return

        def job() -> None:
            code, out = installer.install(on_line=lambda ln: self._ui(self._status, ln[:160]))
            if code == 0:
                import importlib

                importlib.invalidate_caches()
                self._ui(self._status, "Packages installed.")
            else:
                self._ui(self._show_error, "Install failed", out[-1500:])
            self._ui(self._refresh_sam_status)

        self._submit("Installing packages", job)

    # -- v1 DepthEditorGUI._download_weights (depth_editor_gui.py:1463)
    def _download_weights(self) -> None:
        if self._job_pending():
            return

        def job() -> None:
            try:
                sam.download_weights(progress=lambda msg: self._ui(self._status, msg))
                self._ui(self._status, f"{sam.model_label(sam.DEFAULT_VERSION)} weights downloaded. "
                                       "Unload the model to switch to them.")
            except sam.WeightsAccessError as e:
                self._ui(self._show_error, "SAM 3 access needed", str(e))
            self._ui(self._refresh_sam_status)

        self._submit("Downloading weights", job)

    # -- v1 DepthEditorGUI._layer (depth_editor_gui.py:1482)
    def _layer(self) -> Optional[Layer]:
        if self.project is None or self.selected is None:
            return None
        if 0 <= self.selected < len(self.project.layers):
            return self.project.layers[self.selected]
        return None

    # -- v1 DepthEditorGUI._new_layer (depth_editor_gui.py:1489)
    def _new_layer(self) -> Optional[Layer]:
        if self.project is None or self.info is None:
            self._status("Load a clip first.")
            return None
        layer = self.project.new_layer(self.info.height, self.info.width, source=self.layer_source_var.get())
        self.selected = len(self.project.layers) - 1
        self._refresh_layer_panel()
        return layer

    # -- v1 DepthEditorGUI._delete_layer (depth_editor_gui.py:1498)
    def _delete_layer(self) -> None:
        layer = self._layer()
        if layer is None:
            return
        if (layer.has_prompts() or len(layer.masks)) and not messagebox.askyesno(
                "Delete layer", f'Delete "{layer.name}" and its masks?', parent=self.winfo_toplevel()):
            return
        if self.engine.owner == layer.uid:
            self.engine.owner = None
        del self.project.layers[self.selected]
        self.selected = min(self.selected, len(self.project.layers) - 1) if self.project.layers else None
        self._refresh_layer_panel()
        self._schedule_preview()

    # -- v1 DepthEditorGUI._move_layer (depth_editor_gui.py:1512)
    def _move_layer(self, delta: int) -> None:
        layer = self._layer()
        if layer is None:
            return
        j = self.selected + delta
        if not 0 <= j < len(self.project.layers):
            return
        layers = self.project.layers
        layers[self.selected], layers[j] = layers[j], layers[self.selected]
        self.selected = j
        self._refresh_layer_panel()
        self._schedule_preview()

    # -- v1 DepthEditorGUI._on_layer_select (depth_editor_gui.py:1525)
    def _on_layer_select(self) -> None:
        sel = self.layer_list.curselection()
        if not sel:
            return
        self.selected = int(sel[0])
        self._refresh_layer_panel(keep_list=True)
        self._schedule_preview()

    # -- v1 DepthEditorGUI._refresh_layer_panel (depth_editor_gui.py:1533)
    def _refresh_layer_panel(self, keep_list: bool = False) -> None:
        layers = self.project.layers if self.project else []
        if not keep_list:
            self.layer_list.delete(0, tk.END)
            for layer in layers:
                mark = "" if layer.enabled else "  (off)"
                self.layer_list.insert(tk.END, f"  {layer.name}{mark}")
            for i, layer in enumerate(layers):
                self.layer_list.itemconfigure(i, foreground=layer.colour)
            if self.selected is not None and self.selected < len(layers):
                self.layer_list.selection_clear(0, tk.END)
                self.layer_list.selection_set(self.selected)
        layer = self._layer()
        self._loading_vars = True
        try:
            if layer is None:
                self.layer_info_var.set("No layer. Click the picture, drag a box or Find to start one.")
                self.layer_name_var.set("")
                return
            self.layer_name_var.set(layer.name)
            self.layer_enabled_var.set(layer.enabled)
            self.layer_source_var.set(layer.source)
            for path, var in self._layer_controls:
                var.set(_get_path(keys.settings_at(layer.settings, layer.keys, self.frame_idx), path))  # v2
            self._refresh_range_label(layer)
            objects = {c.obj_id for c in layer.clicks}
            parts = [f"Segments on {layer.source}"]
            if layer.text:
                parts.append(f'finds "{layer.text}"')
            if objects:
                parts.append(f"{len(objects)} clicked object{'s' if len(objects) != 1 else ''}")
            n = self._num_frames()
            if layer.tracked:
                parts.append(f"tracked: object on {len(layer.masks)}/{n} frames")
            elif len(layer.masks):
                parts.append("not tracked yet")
            self.layer_info_var.set(" · ".join(parts))
        finally:
            self._loading_vars = False

    # -- v1 DepthEditorGUI._on_layer_name (depth_editor_gui.py:1573)
    def _on_layer_name(self) -> None:
        layer = self._layer()
        if layer is None or self._loading_vars:
            return
        layer.name = self.layer_name_var.get()
        if self.selected is not None:
            mark = "" if layer.enabled else "  (off)"
            self.layer_list.delete(self.selected)
            self.layer_list.insert(self.selected, f"  {layer.name}{mark}")
            self.layer_list.itemconfigure(self.selected, foreground=layer.colour)
            self.layer_list.selection_set(self.selected)

