    # -- v1 DepthEditorGUI._save_project (depth_editor_gui.py:1727)
    def _save_project(self, quiet: bool = False) -> Optional[str]:
        if self.project is None or self.info is None:
            return None
        out_dir = self.output_dir_var.get().strip()
        if not out_dir:
            messagebox.showerror("Depth Map Editor", "Choose an output folder.", parent=self.winfo_toplevel())
            return None
        os.makedirs(out_dir, exist_ok=True)
        path = project_path_for(out_dir, self.project.depth_path)
        self.project.save(path)
        if not quiet:
            self._status(f"Saved {os.path.basename(path)}.")
        return path

    # -- v1 DepthEditorGUI._render (depth_editor_gui.py:1741)
    def _render(self) -> None:
        if self.project is None or self.info is None:
            self._status("Load a clip first.")
            return
        out_dir = self.output_dir_var.get().strip()
        if not out_dir:
            messagebox.showerror("Depth Map Editor", "Choose an output folder.", parent=self.winfo_toplevel())
            return
        out_path = output_depth_path(out_dir, self.project.depth_path).replace("\\", "/")
        if os.path.normcase(os.path.abspath(out_path)) == os.path.normcase(os.path.abspath(self.project.depth_path)):
            messagebox.showerror("Depth Map Editor", "The output would overwrite the depth map being read.\n"
                                 "Choose a different output folder.", parent=self.winfo_toplevel())
            return
        untracked = [ly.name for ly in self.project.layers if ly.enabled and ly.has_prompts() and not ly.tracked]
        if untracked and not messagebox.askyesno(
                "Depth Map Editor", "These layers have not been tracked through the clip, so they only edit the "
                "frames you prompted on:\n\n  " + "\n  ".join(untracked) + "\n\nRender anyway?",
                parent=self.winfo_toplevel()):
            return
        if os.path.exists(out_path) and not messagebox.askyesno(
                "Depth Map Editor", f"Replace the existing\n{out_path}?", parent=self.winfo_toplevel()):
            return
        _save_copy = self.project.snapshot()  # v2: saved by the job, off the UI thread
        _save_path = project_path_for(out_dir, self.project.depth_path)
        self._save_settings()
        # Copies taken now, on the main thread: the sliders stay live while
        # the render runs, and the render must be of what was on screen when
        # it was started.
        info = self.info
        glob = copy.deepcopy(self.project.global_settings)
        layers = [(copy.deepcopy(ly.settings), ly.masks.snapshot()) for ly in self.project.layers if ly.enabled]
        # v2 (user, 2026-10-03): Render at source resolution -- the edit at the RGB's size, the
        # RGB layers with their full-size masks (core.depthedit.hires)
        layers_keys = [copy.deepcopy(ly.keys) for ly in self.project.layers if ly.enabled]  # v2: keyframes
        layers_hi = [ly.masks_hi.snapshot() if ly.masks_hi is not None else None
                     for ly in self.project.layers if ly.enabled]
        hi_size = hires.source_size(self.project.rgb_path) if self.render_hires_var.get() else None
        if hi_size and tuple(hi_size) == (info.width, info.height):
            hi_size = None   # v2: Upscale Map read the map at that size already
        out_info = hires.info_at(info, hi_size)
        rgb_path = self.project.rgb_path
        handoff = self.handoff_var.get()

        def job() -> None:
            try:  # v2: the project first, as it was when Render was pressed
                os.makedirs(out_dir, exist_ok=True)
                _save_copy.save(_save_path)
            except Exception:
                logger.exception("Could not save the project %s", _save_path)
            tmp = out_path[:-4] + ".partial.mp4"
            writer = depth_io.DepthWriter(tmp, out_info)
            n = 0
            t0 = time.time()
            try:
                for idx, codes in enumerate(depth_io.iter_codes(info, self._stop)):
                    if hi_size:
                        stack3 = [(keys.settings_at(s, k, idx), store.get(idx, s.steady),
                                   hi.get(idx, s.steady) if hi is not None else None)  # v2: Steady
                                  for (s, store), hi, k in zip(layers, layers_hi, layers_keys)]
                        unit = hires.render_frame(depth_io.to_unit(codes, info), glob, stack3, idx, hi_size)
                    else:
                        stack = [(keys.settings_at(s, k, idx), store.get(idx, s.steady))  # v2: Steady
                                 for (s, store), k in zip(layers, layers_keys)]
                        unit = edit_ops.apply_all(depth_io.to_unit(codes, info), glob, stack, idx)
                    writer.write(depth_io.from_unit(unit, info))
                    n = idx + 1
                    if n % 8 == 0 or n == info.num_frames:
                        self._ui(self._render_progress, n, info.num_frames)
                if self._stop.is_set():
                    writer.abort()
                    _remove_quietly(tmp)
                    self._ui(self._status, "Render stopped; nothing was written.")
                    return
                writer.close()
            except Exception:
                writer.abort()
                _remove_quietly(tmp)
                raise
            written = depth_io.probe(tmp)
            if written.num_frames != info.num_frames:
                _remove_quietly(tmp)
                raise RuntimeError(f"Wrote {written.num_frames} frames, expected {info.num_frames}.")
            os.replace(tmp, out_path)
            self._ui(self._render_progress, info.num_frames, info.num_frames)
            self._ui(self._status, f"Wrote {out_path} ({n} frames at {out_info.width}x{out_info.height}, "
                                   f"{time.time() - t0:.1f}s).")
            if handoff:
                self._record_job_handoff(rgb_path, out_path)

        self._submit("Rendering", job)

    # -- v1 DepthEditorGUI._render_progress (depth_editor_gui.py:1809)
    def _render_progress(self, done: int, total: int) -> None:
        self.render_progress["value"] = 100.0 * done / max(total, 1)
        self._status(f"Rendering... {done}/{total}")

    # -- v1 DepthEditorGUI._record_job_handoff (depth_editor_gui.py:1813)
    def _record_job_handoff(self, rgb_path: str, out_path: str) -> None:
        """Offer this clip to Splatting's import button.

        Recorded as one clip and one map, not folders: the editor works a
        clip at a time, and Splatting takes a single file in either box.
        """
        try:
            from core.ui.job_handoff import record_job

            record_job("depthedit", {"source": rgb_path, "depth": out_path})
        except Exception:
            logger.debug("Could not record job handoff", exc_info=True)
